powerpagecomponent.content:
{
  "source": "{% assign appId = request.params['record'] | default: request.params['id'] %}
{% fetchxml sectionJsonSchema %}
<fetch>
  <entity name="cmdspp_pc_enrol_page_json_tb">
    <attribute name="cmdspp_p_jsontxt" />
    <attribute name="cmdspp_p_table_nam" />
    <attribute name="cmdspp_p_page_nam" />
    <filter>
      <condition attribute="cmdspp_p_page_nam" operator="eq" value="ownership" />
    </filter>
  </entity>
</fetch>
{% endfetchxml %}

{% include 'cmdspp_Enrollment-PP-commonPopUP' %}

<script id="wizardSchemaData" type="application/json">
[
{% assign firstRecord = true %}
{% for rec in sectionJsonSchema.results.entities %}

  {% if rec.cmdspp_p_table_nam == 'cmdspp_p_ownership_dtl_tbs'or rec.cmdspp_p_table_nam == 'cmdspp_p_ownership_dtl_tbs_1'or rec.cmdspp_p_table_nam == 'cmdspp_p_subcontractor_dtl_tbs'or rec.cmdspp_p_table_nam == 'cmdspp_p_relative_dtl_tbs' %}

    {% unless firstRecord %},{% endunless %}
    {{ rec.cmdspp_p_jsontxt }}
    {% assign firstRecord = false %}

  {% endif %}

{% endfor %}
]
</script>

<script>
  (function () {

    var schemaElement = document.getElementById("wizardSchemaData");

    if (!schemaElement) {
      console.error("wizardSchemaData element not found.");
      return;
    }

    var wizardSchema = JSON.parse(
      schemaElement.textContent || "[]"
    );

    wizardSchema.sort(function (a, b) {

      var prefixA = String(
        a.headerPrefix || ""
      ).trim();

      var prefixB = String(
        b.headerPrefix || ""
      ).trim();

      return prefixA.localeCompare(
        prefixB,
        undefined,
        {
          numeric: true,
          sensitivity: "base"
        }
      );
    });

    window.wizardSchema = wizardSchema;

    console.log(
      "Ownership Common Template Schema:",
      wizardSchema
    );

  })();
</script>
<div class="alert alert-light border mb-3">
  <label class="form-check-label">
    <input type="checkbox"
           id="ownershipCertification"
           class="form-check-input me-2">

    By continuing with this application, I, the submitter, confirm that the Ownership and Controlling Interest information entered is complete and accurate at the time of submission. Completion of this section is a condition of participation in the Medicaid program and is mandated by
    <a href="https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-C/part-455/subpart-B?toc=1"
       target="_blank"
       rel="noopener noreferrer"
       class="ownership-link">
       42 CFR 455.100-106
    </a>.
    Click to view the full regulation.
  </label>
</div>

{% include 'common_page_template' %}


<script>

  async function loadOwnershipCertification() {

    const checkbox =
      document.getElementById("ownershipCertification");

    if (!checkbox) return;

    const parentId =
      new URLSearchParams(window.location.search).get("record") ||
      new URLSearchParams(window.location.search).get("id");

    if (!parentId) return;

    try {

      const result = await window.webapi.safeAjax({
        type: "GET",
        url:
          "/_api/cmdspp_p_ownership_dtl_tbs" +
          "?$select=cmdspp_p_ownership_dtl_tbid,cmdspp_p_ownershipcertification" +
          "&$filter=_cmdspp_p_sys_id_value eq " +
          parentId +
          " and statecode eq 0"
      });

      if (result.value && result.value.length > 0) {

        const ownershipRecord =
          result.value[0];

        window.ownershipRecordId =
          ownershipRecord.cmdspp_p_ownership_dtl_tbid;

        checkbox.checked =
          ownershipRecord.cmdspp_p_ownershipcertification === true;
          toggleSections(
  !ownershipRecord.cmdspp_p_ownershipcertification
);
      }

    } catch (error) {

      console.error(
        "Failed to load ownership certification",
        error
      );
    }
  }

  async function updateOwnershipCertification() {

    const checkbox =
      document.getElementById("ownershipCertification");

    if (!checkbox) return;

    const parentId =
      new URLSearchParams(window.location.search).get("record") ||
      new URLSearchParams(window.location.search).get("id");

    if (!parentId) return;

    try {

      await window.webapi.safeAjax({
        type: "PATCH",
        url:
          "/_api/cmdspp_p_ownership_dtl_tbs(" +
          window.ownershipRecordId +
          ")",
        contentType: "application/json",
        data: JSON.stringify({
          cmdspp_p_ownershipcertification:
            checkbox.checked
        })
      });

    } catch (error) {

      console.error(
        "Failed to update ownership certification",
        error
      );

    }
  }

  $(document).ready(function () {

    // Fetch value when user opens page
    loadOwnershipCertification();

    // Update value whenever checkbox changes
  $(document).on(
    "change",
    "#ownershipCertification",
    async function () {

        const checkbox = this;

        if (!checkbox.checked) {

            showConfirmationPopup({

                title: "Data Loss Warning",

                message:
                    "Unchecking this certification will remove all Ownership, Managing Information, Subcontractor, and Relative records. Do you want to continue?",

                confirmText: "Yes",

                cancelText: "No",

                onConfirm: async function () {

    try {

        await updateOwnershipCertification();

        toggleSections(true);

    } catch (e) {

        console.error(e);

        checkbox.checked = true;
    }
},

                onCancel: function () {

                    checkbox.checked = true;

                }
            });

        } else {

            try {

                await updateOwnershipCertification();

                toggleSections(false);

            } catch (e) {

                console.error(e);

                checkbox.checked = false;

            }
        }
    }
);

  });

function toggleSections(disabled) {

    document
        .querySelectorAll(".accordion-container")
        .forEach(function (section) {

            section.style.pointerEvents =
                disabled ? "none" : "";

            section.style.opacity =
                disabled ? "0.6" : "1";

            section
                .querySelectorAll(
                    "input,select,textarea,button"
                )
                .forEach(function (el) {

                    if (
                        el.id !==
                        "ownershipCertification"
                    ) {
                        el.disabled = disabled;
                    }

                });
        });
}
document.addEventListener("click", function(e) {
    if (e.target.closest(".ownership-link")) {
        e.stopPropagation();
    }
});
</script>

<style>
#ownershipContainer .col-md-12,
#manageInfoContainer .col-md-12,
#subcontractorContainer .col-md-12,
#relativeContainer .col-md-12 {
    width: 100% !important;
}
.ownership-link {
    color: #0d6efd;
    text-decoration: underline;
    cursor: pointer;
}

.ownership-link:hover {
    color: #0196F3;
}
  </style>"
}
